// Only validated public compiler files are cached. CVs and PDFs stay in memory.
const CACHE = 'cv-anonymiser-latex-verified-v2';
const FILES = ['swiftlatexpdftex.wasm', 'tex-files.bin', 'swiftlatexpdftex.js'];
// Generated by scripts/prepare-latex-assets.py; hashes refer to decoded bytes.
const ASSETS = {"bytes":{"swiftlatexpdftex.js":83934,"swiftlatexpdftex.wasm":1772266,"tex-files.bin":15729554},"sha256":{"swiftlatexpdftex.js":"1b89a17c1a31237d81c9e4d12e386182daebe82c4b1288c2a61eb76e8148de0a","swiftlatexpdftex.wasm":"a2847460f4c55e623e2ccd4898ee629596a1ce121395eeda1cfbdf7a94893c62","tex-files.bin":"9196a53bc5fbb683c3417d73122613780bc4d4d6a42edc237989b7229117a9f4"}};
const loaded = new Map();
let total = 0;
let lastProgress = 0;

function progress(name, bytes, force = false) {
  loaded.set(name, bytes);
  if (!force && Date.now() - lastProgress < 150) return;
  lastProgress = Date.now();
  const complete = [...loaded.values()].reduce((sum, value) => sum + value, 0);
  const percent = Math.min(100, Math.floor(complete / total * 100));
  self.postMessage({ type: 'progress', message: `Loading compiler: ${(complete / 1e6).toFixed(1)} / ${(total / 1e6).toFixed(1)} MB (${percent}%)…` });
}

async function timed(operation, cancel = () => {}) {
  let timer;
  try {
    return await Promise.race([operation, new Promise((_, reject) => {
      timer = setTimeout(() => { cancel(); reject(new Error('The compiler download stopped responding.')); }, 45000);
    })]);
  } finally { clearTimeout(timer); }
}

async function responseBytes(response, expected, update, abort) {
  if (!response.body) return timed(response.arrayBuffer(), abort);
  const reader = response.body.getReader();
  const buffer = new Uint8Array(expected);
  let length = 0;
  try {
    while (true) {
      const { done, value } = await timed(reader.read(), () => {
        abort?.();
        reader.cancel().catch(() => {});
      });
      if (done) break;
      if (length + value.byteLength > expected) throw new Error('The compiler download has an unexpected size.');
      buffer.set(value, length);
      length += value.byteLength;
      update?.(length);
    }
    if (length !== expected) throw new Error('The compiler download was incomplete.');
    return buffer.buffer;
  } finally { reader.releaseLock(); }
}

async function valid(bytes, expected, hash) {
  if (bytes.byteLength !== expected) return false;
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
  return [...digest].map((byte) => byte.toString(16).padStart(2, '0')).join('') === hash;
}

async function asset(name, info) {
  const url = new URL(name, self.__cvAssetBase || self.location.href);
  // Hash keys reuse unchanged files across the publisher's release directories.
  const key = `${url.origin}/__cv-anonymiser-latex/${info.sha256[name]}`;
  const expected = info.bytes[name];
  let cache;
  try {
    cache = await caches.open(CACHE);
    const saved = await cache.match(key);
    if (saved) {
      try {
        const bytes = await responseBytes(saved, expected);
        if (await valid(bytes, expected, info.sha256[name])) {
          progress(name, expected, true);
          return bytes;
        }
      } catch { /* Discard unreadable cache entries and fetch a clean copy. */ }
      await cache.delete(key);
    }
  } catch { /* Storage failures must not prevent compilation. */ }

  for (let attempt = 0; attempt < 2; attempt++) {
    const controller = new AbortController();
    progress(name, 0);
    try {
      const response = await timed(fetch(url.href, { credentials: 'omit', cache: attempt ? 'reload' : 'default', signal: controller.signal }), () => controller.abort());
      if (!response.ok) throw new Error(`Compiler download returned HTTP ${response.status}.`);
      const bytes = await responseBytes(response, expected, (size) => progress(name, size), () => controller.abort());
      if (!await valid(bytes, expected, info.sha256[name])) throw new Error('The compiler download was incomplete or damaged.');
      // Fetch bodies are already HTTP-decoded. Do not preserve wire-level
      // Content-Length/Content-Encoding headers or delay compilation for disk IO.
      try { cache?.put(key, new Response(bytes)).catch(() => {}); } catch { /* Optional cache writes must not turn a complete download into a failure. */ }
      progress(name, expected, true);
      return bytes;
    } catch {
      controller.abort();
      if (attempt === 1) throw new Error('The compiler download could not finish. Check your connection and press Compile PDF to retry.');
      self.postMessage({ type: 'progress', message: 'The compiler download was interrupted. Retrying once…' });
    }
  }
}

async function start() {
  if (typeof DecompressionStream !== 'function') throw new Error('This browser cannot load the PDF compiler. Please use a current browser.');
  self.postMessage({ type: 'progress', message: 'Checking compiler files…' });
  const info = ASSETS;
  if (!FILES.every((name) => Number.isSafeInteger(info?.bytes?.[name]) && info.bytes[name] > 0 && info.bytes[name] < 50e6 && /^[a-f0-9]{64}$/.test(info.sha256?.[name]))) throw new Error('Compiler file metadata is missing from this build.');
  total = FILES.reduce((sum, name) => sum + info.bytes[name], 0);
  const [wasm, packed, loader] = await Promise.all(FILES.map((name) => asset(name, info)));
  self.postMessage({ type: 'progress', message: 'Preparing compiler and fonts…' });
  const unpacked = await new Response(new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
  const bytes = new Uint8Array(unpacked);
  const manifestLength = new DataView(unpacked).getUint32(0, true);
  const start = 4 + manifestLength;
  if (start > bytes.length) throw new Error('The compiler bundle is damaged.');
  const entries = JSON.parse(new TextDecoder().decode(bytes.subarray(4, start)));
  self.__cvTexFiles = Object.create(null);
  for (const [key, offset, length] of entries) {
    if (!/^(3|10|11|26|32|33|44)\/[^/]+$/.test(key) || offset < 0 || length < 0 || start + offset + length > bytes.length) throw new Error('The compiler bundle is damaged.');
    self.__cvTexFiles[key] = bytes.subarray(start + offset, start + offset + length);
  }
  self.__cvWasm = new Uint8Array(wasm);
  const url = URL.createObjectURL(new Blob([loader], { type: 'text/javascript' }));
  try { importScripts(url); } finally { URL.revokeObjectURL(url); }
}

start().catch((error) => self.postMessage({ type: 'error', message: error.message || 'The PDF compiler could not load.' }));
